import { toCss } from '../core/color';
import { compositeFrame, sampleComposite } from '../core/composite';
import type { Point } from '../core/geometry';
import { ellipseSpans, fillPolygon, floodFill } from '../core/raster';
import type { SelectionMode } from '../core/selection';
import type { Viewport } from '../render/viewport';
import { MoveSession } from './move-session';
import { strokeTwoTone } from './paint-tools';
import { docRectPath } from './shape-tools';
import { type OptionSpec, SELECT_MODE_CHOICES, Tool, type ToolId, type ToolPointer } from './tool';

export class FillTool extends Tool {
  readonly id: ToolId = 'fill';
  readonly label = 'Fill';
  override readonly shortcut = 'G';
  override readonly optionsKey = 'fill';
  override readonly paints = true;
  override readonly altPicks = true;
  override readonly editsPixels = true;
  override readonly optionSpecs: OptionSpec[] = [
    { type: 'slider', key: 'tolerance', label: 'Tolerance', min: 0, max: 255, step: 1 },
    { type: 'slider', key: 'opacity', label: 'Opacity', min: 0.01, max: 1, step: 0.01, percent: true },
    { type: 'toggle', key: 'contiguous', label: 'Contiguous', title: 'Only fill connected pixels' },
    { type: 'toggle', key: 'sampleMerged', label: 'All layers', title: 'Detect regions using all visible layers' },
  ];

  override down(p: ToolPointer): void {
    const e = this.editor;
    const doc = e.doc;
    const w = e.wrapPoint(p.x, p.y);
    const x = Math.floor(w.x);
    const y = Math.floor(w.y);
    if (x < 0 || y < 0 || x >= doc.width || y >= doc.height) return;
    if (!e.canEditPixels()) return;
    const o = e.options.fill;
    const src = o.sampleMerged ? compositeFrame(doc, doc.activeFrame) : doc.activeCel.data;
    const session = e.beginPaint({ color: p.button === 2 ? e.bg : e.fg, opacity: o.opacity, mode: 'paint', alphaLock: doc.activeLayer.alphaLocked });
    const r = floodFill(src, doc.width, doc.height, x, y, o.tolerance, o.contiguous, session.mask, doc.selection.mask);
    if (r) session.markDirty(r);
    e.commitPaint(session, 'Fill');
  }
}

export class PickerTool extends Tool {
  readonly id: ToolId = 'picker';
  readonly label = 'Color picker';
  override readonly shortcut = 'I';
  override readonly optionsKey = 'picker';
  override readonly optionSpecs: OptionSpec[] = [
    { type: 'toggle', key: 'sampleMerged', label: 'All layers', title: 'Pick the visible color instead of the active layer' },
  ];
  private dragging = false;
  private target: 'fg' | 'bg' = 'fg';

  override get busy(): boolean {
    return this.dragging;
  }

  override down(p: ToolPointer): void {
    this.dragging = true;
    this.target = p.button === 2 ? 'bg' : 'fg';
    this.hoverPoint = p;
    this.pick(p);
    this.editor.renderer.requestRender();
  }

  override move(p: ToolPointer): void {
    this.hoverPoint = p;
    if (!this.dragging) return;
    this.pick(p);
    this.editor.renderer.requestRender();
  }

  override up(): void {
    this.dragging = false;
    this.editor.renderer.requestRender();
  }

  override cancel(): void {
    this.dragging = false;
  }

  /** Picks a color; used by this tool and by Alt+click in paint tools. */
  pick(p: { x: number; y: number }, target: 'fg' | 'bg' = this.target, merged = this.editor.options.picker.sampleMerged): void {
    const e = this.editor;
    const doc = e.doc;
    const w = e.wrapPoint(p.x, p.y);
    const x = Math.floor(w.x);
    const y = Math.floor(w.y);
    if (x < 0 || y < 0 || x >= doc.width || y >= doc.height) return;
    const [r, g, b, a] = merged ? sampleComposite(doc, doc.activeFrame, x, y) : doc.activeCel.getPixel(x, y);
    if (a === 0) return; // Transparent: keep the current color.
    e.setColor(target, { r, g, b, a });
  }

  protected override hasCursorOverlay(): boolean {
    return true;
  }

  override drawOverlay(ctx: CanvasRenderingContext2D, view: Viewport): void {
    const p = this.hoverPoint;
    if (!p || !this.dragging) return;
    // Loupe offset above the finger (or beside the cursor) so it stays visible.
    const px = Math.floor(p.x);
    const py = Math.floor(p.y);
    const c = view.docToScreen(px + 0.5, py + 0.5);
    const touch = p.pointerType === 'touch';
    const cx = touch ? c.x : c.x + 64;
    const cy = touch ? c.y - 96 : c.y - 64;
    const R = 46;
    const color = this.target === 'bg' ? this.editor.bg : this.editor.fg;
    // Magnified pixels around the picked one (each about 9 screen pixels).
    const cells = 11;
    const cell = (R * 2) / cells;
    const img = this.editor.renderer.compositeImage;
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = '#2c2f33';
    ctx.fillRect(cx - R, cy - R, R * 2, R * 2);
    ctx.imageSmoothingEnabled = false;
    const half = (cells - 1) / 2;
    const w = this.editor.wrapPoint(px, py);
    ctx.drawImage(img, w.x - half, w.y - half, cells, cells, cx - R, cy - R, cells * cell, cells * cell);
    // Center pixel frame.
    ctx.lineWidth = 1;
    ctx.strokeStyle = '#000';
    ctx.strokeRect(cx - cell / 2 - 0.5, cy - cell / 2 - 0.5, cell + 1, cell + 1);
    ctx.strokeStyle = '#fff';
    ctx.strokeRect(cx - cell / 2 + 0.5, cy - cell / 2 + 0.5, cell - 1, cell - 1);
    ctx.restore();
    // Ring in the picked color around the loupe.
    ctx.beginPath();
    ctx.arc(cx, cy, R + 6, 0, Math.PI * 2);
    ctx.lineWidth = 12;
    ctx.strokeStyle = toCss({ ...color, a: 255 });
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(cx, cy, R + 12, 0, Math.PI * 2);
    ctx.moveTo(cx + R, cy);
    ctx.arc(cx, cy, R, 0, Math.PI * 2);
    strokeTwoTone(ctx);
  }
}

/** Selection mode from modifier keys (Shift add, Alt subtract, both intersect), else the option. */
function selectionModeFor(p: ToolPointer, fallback: SelectionMode): SelectionMode {
  if (p.shift && p.alt) return 'intersect';
  if (p.shift) return 'add';
  if (p.alt) return 'subtract';
  return fallback;
}

abstract class DragSelectTool extends Tool {
  override readonly optionsKey = 'select';
  override readonly optionSpecs: OptionSpec[] = [{ type: 'choice', key: 'mode', label: 'Mode', choices: SELECT_MODE_CHOICES }];
  protected startPt: Point | null = null;
  protected curPt: Point | null = null;
  protected mode: SelectionMode = 'replace';

  override get busy(): boolean {
    return this.startPt !== null;
  }

  protected snap(p: Point): Point {
    const g = this.editor.gridSnap();
    if (g) return { x: Math.round(p.x / g.w) * g.w, y: Math.round(p.y / g.h) * g.h };
    return { x: Math.round(p.x), y: Math.round(p.y) };
  }

  override down(p: ToolPointer): void {
    this.mode = selectionModeFor(p, this.editor.options.select.mode);
    this.startPt = this.snap(p);
    this.curPt = this.startPt;
  }

  override move(p: ToolPointer): void {
    this.hoverPoint = p;
    if (!this.startPt) return;
    this.curPt = this.snap(p);
    const r = this.box();
    this.editor.setStatusHint(`${r.w} × ${r.h}`);
    this.editor.renderer.requestRender();
  }

  protected box(): { x: number; y: number; w: number; h: number } {
    const a = this.startPt!;
    const b = this.curPt!;
    return { x: Math.min(a.x, b.x), y: Math.min(a.y, b.y), w: Math.abs(b.x - a.x), h: Math.abs(b.y - a.y) };
  }

  protected abstract buildMask(r: { x: number; y: number; w: number; h: number }, out: Uint8Array): void;

  override up(): void {
    if (!this.startPt) return;
    const e = this.editor;
    const r = this.box();
    this.startPt = null;
    e.setStatusHint('');
    if (r.w < 1 || r.h < 1) {
      // A click without a drag deselects (in replace mode).
      if (this.mode === 'replace') e.deselect();
      e.renderer.requestRender();
      return;
    }
    const mask = new Uint8Array(e.doc.width * e.doc.height);
    this.buildMask(r, mask);
    e.applySelection(mask, r, this.mode, this.label);
  }

  override cancel(): void {
    this.startPt = null;
    this.editor.setStatusHint('');
    this.editor.renderer.requestRender();
  }

  override drawOverlay(ctx: CanvasRenderingContext2D, view: Viewport): void {
    if (!this.startPt || !this.curPt) return;
    const r = this.box();
    this.previewPath(ctx, view, r);
    ctx.setLineDash([]);
    ctx.lineWidth = 1;
    ctx.strokeStyle = '#000';
    ctx.stroke();
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = '#fff';
    ctx.stroke();
  }

  protected previewPath(ctx: CanvasRenderingContext2D, view: Viewport, r: { x: number; y: number; w: number; h: number }): void {
    docRectPath(ctx, view, r.x, r.y, r.x + r.w, r.y + r.h);
  }
}

export class RectSelectTool extends DragSelectTool {
  readonly id: ToolId = 'select-rect';
  readonly label = 'Rectangle select';
  override readonly shortcut = 'S';

  protected buildMask(r: { x: number; y: number; w: number; h: number }, out: Uint8Array): void {
    const W = this.editor.doc.width;
    const H = this.editor.doc.height;
    const x0 = Math.max(0, r.x);
    const x1 = Math.min(W, r.x + r.w);
    for (let y = Math.max(0, r.y); y < Math.min(H, r.y + r.h); y++) if (x1 > x0) out.fill(255, y * W + x0, y * W + x1);
  }
}

export class EllipseSelectTool extends DragSelectTool {
  readonly id: ToolId = 'select-ellipse';
  readonly label = 'Ellipse select';

  protected buildMask(r: { x: number; y: number; w: number; h: number }, out: Uint8Array): void {
    const W = this.editor.doc.width;
    const H = this.editor.doc.height;
    ellipseSpans(r.x, r.y, r.x + r.w - 1, r.y + r.h - 1, (y, a, b) => {
      if (y < 0 || y >= H) return;
      const xa = Math.max(0, a);
      const xb = Math.min(W - 1, b);
      if (xb >= xa) out.fill(255, y * W + xa, y * W + xb + 1);
    });
  }

  protected override previewPath(ctx: CanvasRenderingContext2D, view: Viewport, r: { x: number; y: number; w: number; h: number }): void {
    ctx.beginPath();
    const steps = 64;
    for (let i = 0; i <= steps; i++) {
      const t = (i / steps) * Math.PI * 2;
      const q = view.docToScreen(r.x + r.w / 2 + (Math.cos(t) * r.w) / 2, r.y + r.h / 2 + (Math.sin(t) * r.h) / 2);
      if (i) ctx.lineTo(q.x, q.y);
      else ctx.moveTo(q.x, q.y);
    }
    ctx.closePath();
  }
}

export class LassoTool extends Tool {
  readonly id: ToolId = 'lasso';
  readonly label = 'Lasso select';
  override readonly optionsKey = 'select';
  override readonly optionSpecs: OptionSpec[] = [{ type: 'choice', key: 'mode', label: 'Mode', choices: SELECT_MODE_CHOICES }];
  private points: Point[] = [];
  private mode: SelectionMode = 'replace';
  private active = false;

  override get busy(): boolean {
    return this.active;
  }

  override down(p: ToolPointer): void {
    this.mode = selectionModeFor(p, this.editor.options.select.mode);
    this.points = [{ x: p.x, y: p.y }];
    this.active = true;
  }

  override move(p: ToolPointer): void {
    if (!this.active) return;
    const last = this.points[this.points.length - 1];
    if (Math.hypot(p.x - last.x, p.y - last.y) * this.editor.view.zoom >= 2) {
      this.points.push({ x: p.x, y: p.y });
      this.editor.renderer.requestRender();
    }
  }

  override up(): void {
    if (!this.active) return;
    this.active = false;
    const e = this.editor;
    const pts = this.points;
    this.points = [];
    const mask = new Uint8Array(e.doc.width * e.doc.height);
    const r = pts.length >= 3 ? fillPolygon(pts, e.doc.width, e.doc.height, mask) : null;
    if (!r) {
      if (this.mode === 'replace') e.deselect();
      e.renderer.requestRender();
      return;
    }
    e.applySelection(mask, r, this.mode, 'Lasso select');
  }

  override cancel(): void {
    this.active = false;
    this.points = [];
    this.editor.renderer.requestRender();
  }

  override drawOverlay(ctx: CanvasRenderingContext2D, view: Viewport): void {
    if (!this.active || this.points.length < 2) return;
    ctx.beginPath();
    this.points.forEach((pt, i) => {
      const q = view.docToScreen(pt.x, pt.y);
      if (i) ctx.lineTo(q.x, q.y);
      else ctx.moveTo(q.x, q.y);
    });
    ctx.lineWidth = 1;
    ctx.strokeStyle = '#000';
    ctx.stroke();
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = '#fff';
    ctx.stroke();
  }
}

export class WandTool extends Tool {
  readonly id: ToolId = 'wand';
  readonly label = 'Magic wand';
  override readonly shortcut = 'W';
  override readonly optionsKey = 'wand';
  override readonly optionSpecs: OptionSpec[] = [
    { type: 'slider', key: 'tolerance', label: 'Tolerance', min: 0, max: 255, step: 1 },
    { type: 'toggle', key: 'contiguous', label: 'Contiguous' },
    { type: 'toggle', key: 'sampleMerged', label: 'All layers' },
  ];

  override down(p: ToolPointer): void {
    const e = this.editor;
    const doc = e.doc;
    const w = e.wrapPoint(p.x, p.y);
    const x = Math.floor(w.x);
    const y = Math.floor(w.y);
    if (x < 0 || y < 0 || x >= doc.width || y >= doc.height) return;
    const o = e.options.wand;
    const src = o.sampleMerged ? compositeFrame(doc, doc.activeFrame) : doc.activeCel.data;
    const mask = new Uint8Array(doc.width * doc.height);
    const r = floodFill(src, doc.width, doc.height, x, y, o.tolerance, o.contiguous, mask);
    if (r) e.applySelection(mask, r, selectionModeFor(p, e.options.select.mode), 'Magic wand');
  }
}

type Handle = { kind: 'scale'; hx: -1 | 0 | 1; hy: -1 | 0 | 1 } | { kind: 'rotate' };

/** Screen distance (px) at which a transform handle is grabbed. */
function handleRadius(p: ToolPointer): number {
  return p.pointerType === 'touch' ? 18 : 9;
}

/**
 * Moves the selection (or the whole layer). While pixels are floating,
 * handles on their box scale (Shift: keep proportions) and rotate them
 * (Shift: 15° steps); dragging inside moves them.
 */
export class MoveTool extends Tool {
  readonly id: ToolId = 'move';
  readonly label = 'Move';
  override readonly shortcut = 'M';
  override readonly editsPixels = true;
  override cursor = 'move';
  private drag: { x: number; y: number; dx0: number; dy0: number } | null = null;
  private xdrag: {
    handle: Handle;
    sx0: number;
    sy0: number;
    angle0: number;
    /** Fixed point (document) while scaling: the opposite handle. */
    anchor: { x: number; y: number };
    start: { x: number; y: number };
    center0: { x: number; y: number };
    dx0: number;
    dy0: number;
  } | null = null;

  override get busy(): boolean {
    return this.drag !== null || this.xdrag !== null;
  }

  private session(): MoveSession | null {
    return this.editor.liftFloating();
  }

  /** Screen positions of the box corners and handles of the floating pixels. */
  private handles(view: Viewport): {
    box: { x: number; y: number }[];
    scale: { h: Handle; x: number; y: number }[];
    rotate: { x: number; y: number };
    topMid: { x: number; y: number };
  } | null {
    const f = this.editor.floating;
    if (!f || f.surface !== this.editor.doc.activeCel) return null;
    const box = f.corners().map((c) => view.docToScreen(c.x, c.y));
    const mid = (a: { x: number; y: number }, b: { x: number; y: number }) => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });
    const [tl, tr, br, bl] = box;
    const scale: { h: Handle; x: number; y: number }[] = [
      { h: { kind: 'scale', hx: -1, hy: -1 }, ...tl },
      { h: { kind: 'scale', hx: 1, hy: -1 }, ...tr },
      { h: { kind: 'scale', hx: 1, hy: 1 }, ...br },
      { h: { kind: 'scale', hx: -1, hy: 1 }, ...bl },
      { h: { kind: 'scale', hx: 0, hy: -1 }, ...mid(tl, tr) },
      { h: { kind: 'scale', hx: 1, hy: 0 }, ...mid(tr, br) },
      { h: { kind: 'scale', hx: 0, hy: 1 }, ...mid(br, bl) },
      { h: { kind: 'scale', hx: -1, hy: 0 }, ...mid(bl, tl) },
    ];
    const topMid = mid(tl, tr);
    const c = mid(tl, br);
    const dx = topMid.x - c.x;
    const dy = topMid.y - c.y;
    const len = Math.hypot(dx, dy) || 1;
    // When flipped vertically the "top" edge is at the bottom; the handle stays outside the box.
    const rotate = { x: topMid.x + (dx / len) * 28, y: topMid.y + (dy / len) * 28 };
    return { box, scale, rotate, topMid };
  }

  override down(p: ToolPointer): void {
    const e = this.editor;
    const hs = this.handles(e.view);
    const f = e.floating;
    if (hs && f) {
      const r = handleRadius(p);
      let handle: Handle | null = null;
      if (Math.hypot(p.sx - hs.rotate.x, p.sy - hs.rotate.y) <= r) handle = { kind: 'rotate' };
      else {
        // Small boxes: corners win over edge handles.
        for (const s of hs.scale) {
          if (Math.hypot(p.sx - s.x, p.sy - s.y) <= r) {
            handle = s.h;
            break;
          }
        }
      }
      if (handle) {
        const { w, h } = f.size;
        const { sx, sy, angle } = f.xf;
        const c = f.center;
        const hx = handle.kind === 'scale' ? handle.hx : 0;
        const hy = handle.kind === 'scale' ? handle.hy : 0;
        // Opposite side in local (unrotated, scaled) coordinates → document.
        const ax = (-hx * w * Math.abs(sx)) / 2;
        const ay = (-hy * h * Math.abs(sy)) / 2;
        const cos = Math.cos(angle);
        const sin = Math.sin(angle);
        this.xdrag = {
          handle,
          sx0: sx,
          sy0: sy,
          angle0: angle,
          anchor: { x: c.x + cos * ax - sin * ay, y: c.y + sin * ax + cos * ay },
          start: { x: p.x, y: p.y },
          center0: c,
          dx0: f.dx,
          dy0: f.dy,
        };
        return;
      }
    }
    const s = this.session();
    if (!s) return;
    this.drag = { x: p.x, y: p.y, dx0: s.dx, dy0: s.dy };
  }

  override move(p: ToolPointer): void {
    this.hoverPoint = p;
    const f = this.editor.floating;
    const x = this.xdrag;
    if (x && f) {
      if (x.handle.kind === 'rotate') {
        const a0 = Math.atan2(x.start.y - x.center0.y, x.start.x - x.center0.x);
        const a1 = Math.atan2(p.y - x.center0.y, p.x - x.center0.x);
        let angle = x.angle0 + a1 - a0;
        if (p.shift) angle = Math.round(angle / (Math.PI / 12)) * (Math.PI / 12);
        angle = Math.atan2(Math.sin(angle), Math.cos(angle));
        if (Math.abs(angle) < 1e-9) angle = 0;
        f.setTransform({ angle });
      } else {
        const { hx, hy } = x.handle;
        const { w, h } = f.size;
        const cos = Math.cos(x.angle0);
        const sin = Math.sin(x.angle0);
        // Pointer relative to the anchor, in the box's own (unrotated) axes.
        const vx = cos * (p.x - x.anchor.x) + sin * (p.y - x.anchor.y);
        const vy = -sin * (p.x - x.anchor.x) + cos * (p.y - x.anchor.y);
        let sx = hx ? (Math.sign(x.sx0) * hx * vx) / w : x.sx0;
        let sy = hy ? (Math.sign(x.sy0) * hy * vy) / h : x.sy0;
        if (p.shift && hx && hy) {
          const k = ((hx * vx) / (w * Math.abs(x.sx0)) + (hy * vy) / (h * Math.abs(x.sy0))) / 2;
          sx = x.sx0 * k;
          sy = x.sy0 * k;
        }
        // Never collapse to zero size.
        const minX = 1 / w;
        const minY = 1 / h;
        if (Math.abs(sx) < minX) sx = (Math.sign(sx) || 1) * minX;
        if (Math.abs(sy) < minY) sy = (Math.sign(sy) || 1) * minY;
        // New center: half the new size away from the anchor along each dragged axis.
        const lx = hx ? (hx * w * Math.abs(sx)) / 2 : 0;
        const ly = hy ? (hy * h * Math.abs(sy)) / 2 : 0;
        let cx: number;
        let cy: number;
        if (hx && hy) {
          cx = x.anchor.x + cos * lx - sin * ly;
          cy = x.anchor.y + sin * lx + cos * ly;
        } else if (hx) {
          cx = x.anchor.x + cos * lx;
          cy = x.anchor.y + sin * lx;
        } else {
          cx = x.anchor.x - sin * ly;
          cy = x.anchor.y + cos * ly;
        }
        f.setTransform({ sx, sy }, x.dx0 + cx - x.center0.x, x.dy0 + cy - x.center0.y);
      }
      this.hint(f);
      return;
    }
    const d = this.drag;
    if (!d || !f) return;
    let dx = Math.round(p.x - d.x);
    let dy = Math.round(p.y - d.y);
    const g = this.editor.gridSnap();
    if (g) {
      dx = Math.round(dx / g.w) * g.w;
      dy = Math.round(dy / g.h) * g.h;
    }
    f.moveTo(d.dx0 + dx, d.dy0 + dy);
    this.editor.setStatusHint(`Δ ${Math.round(f.dx)}, ${Math.round(f.dy)}`);
  }

  private hint(f: MoveSession): void {
    const { w, h } = f.size;
    const deg = Math.round((f.xf.angle * 180) / Math.PI);
    this.editor.setStatusHint(`${Math.round(w * Math.abs(f.xf.sx))} × ${Math.round(h * Math.abs(f.xf.sy))} px · ${deg}° · Enter applies, Esc cancels`);
  }

  override up(): void {
    this.drag = null;
    this.xdrag = null;
    this.editor.renderer.requestRender();
  }

  override cancel(): void {
    const d = this.drag;
    const f = this.editor.floating;
    if (d && f) f.moveTo(d.dx0, d.dy0);
    const x = this.xdrag;
    if (x && f) f.setTransform({ sx: x.sx0, sy: x.sy0, angle: x.angle0 }, x.dx0, x.dy0);
    this.drag = null;
    this.xdrag = null;
  }

  override keyDown(e: KeyboardEvent): boolean {
    const step = e.shiftKey ? 10 : 1;
    const dirs: Record<string, [number, number]> = { ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, -step], ArrowDown: [0, step] };
    const d = dirs[e.key];
    if (!d) return false;
    const s = this.session();
    if (s) {
      s.moveTo(s.dx + d[0], s.dy + d[1]);
      this.editor.setStatusHint(`Δ ${Math.round(s.dx)}, ${Math.round(s.dy)}`);
    }
    return true;
  }

  override deactivate(): void {
    super.deactivate();
    this.editor.commitFloating();
  }

  protected override hasCursorOverlay(): boolean {
    return true;
  }

  override drawOverlay(ctx: CanvasRenderingContext2D, view: Viewport): void {
    const hs = this.handles(view);
    if (!hs) return;
    ctx.beginPath();
    hs.box.forEach((q, i) => (i ? ctx.lineTo(q.x, q.y) : ctx.moveTo(q.x, q.y)));
    ctx.closePath();
    ctx.moveTo(hs.topMid.x, hs.topMid.y);
    ctx.lineTo(hs.rotate.x, hs.rotate.y);
    strokeTwoTone(ctx);
    const touch = this.hoverPoint?.pointerType === 'touch';
    const size = touch ? 12 : 8;
    for (const s of hs.scale) {
      ctx.beginPath();
      ctx.rect(s.x - size / 2, s.y - size / 2, size, size);
      ctx.fillStyle = '#fff';
      ctx.fill();
      ctx.lineWidth = 1;
      ctx.strokeStyle = '#1b1d21';
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.arc(hs.rotate.x, hs.rotate.y, size / 2 + 1, 0, Math.PI * 2);
    ctx.fillStyle = '#5aa9ff';
    ctx.fill();
    ctx.strokeStyle = '#fff';
    ctx.stroke();
  }
}

export class HandTool extends Tool {
  readonly id: ToolId = 'hand';
  readonly label = 'Pan';
  override readonly shortcut = 'H';
  override cursor = 'grab';
  private last: { sx: number; sy: number } | null = null;

  override get busy(): boolean {
    return this.last !== null;
  }

  override down(p: ToolPointer): void {
    this.last = { sx: p.sx, sy: p.sy };
  }

  override move(p: ToolPointer): void {
    if (!this.last) return;
    this.editor.view.panBy(p.sx - this.last.sx, p.sy - this.last.sy);
    this.last = { sx: p.sx, sy: p.sy };
    this.editor.viewChanged();
  }

  override up(): void {
    this.last = null;
  }

  override cancel(): void {
    this.last = null;
  }
}
